+static QString documentName(const QUrl &url)
+{
+    if (url.isLocalFile() && !url.fileName().isEmpty()) {
+        return url.fileName();
+    }
+    return url.toDisplayString();
+}
+
+static void setDocumentPinned(const QString &agent, const QUrl &url, bool pinned)
+{
+    KAStats::ResultWatcher watcher(LinkedResources | Agent(agent) | Type::any() | Activity::global());
+    if (pinned) {
+        watcher.linkToActivity(url);
+    } else {
+        watcher.unlinkFromActivity(url);
+    }
+}
+
+QAction *Backend::documentAction(const QUrl &url, const QString &mimetype, const QString &agent, const QUrl &desktopEntryUrl, QObject *parent)
+{
+    QAction *action = new QAction(parent);
+    action->setText(documentName(url));
+    action->setIcon(QIcon::fromTheme(KIO::iconNameForUrl(url)));
+    action->setProperty("agent", agent);
+    action->setProperty("entryPath", desktopEntryUrl);
+    action->setProperty("mimeType", mimetype);
+    action->setData(url);
+    connect(action, &QAction::triggered, this, &Backend::handleRecentDocumentAction);
+    return action;
+}
+
+QAction *Backend::pinDocumentsAction(const QString &text, const QString &iconName, const QList<QUrl> &urls, const QString &agent, bool pin, QObject *parent)
+{
+    QAction *action = new QAction(QIcon::fromTheme(iconName), text, parent);
+    QMenu *subMenu = new QMenu();
+    // See placesActions().
+    subMenu->setAttribute(Qt::WA_TranslucentBackground);
+    connect(parent, &QObject::destroyed, subMenu, &QObject::deleteLater);
+    action->setMenu(subMenu);
+
+    for (const QUrl &url : urls) {
+        QAction *urlAction = subMenu->addAction(QIcon::fromTheme(KIO::iconNameForUrl(url)), documentName(url));
+        connect(urlAction, &QAction::triggered, this, [agent, url, pin] {
+            setDocumentPinned(agent, url, pin);
+        });
+    }
+
+    return action;
+}
+
+static QString documentsAgent(const QUrl &desktopEntryUrl)
+{
+    if (!desktopEntryUrl.isValid() || !desktopEntryUrl.isLocalFile() || !KDesktopFile::isDesktopFile(desktopEntryUrl.toLocalFile())) {
+        return QString();
+    }
+
+    QString storageId = desktopEntryUrl.fileName();
+
+    if (storageId.endsWith(QLatin1String(".desktop"))) {
+        storageId = storageId.left(storageId.length() - 8);
+    }
+
+    return storageId;
+}
+
+static QList<ResultSet::Result> pinnedDocuments(const QString &agent)
+{
+    const ResultSet results(LinkedResources | Agent(agent) | Type::any() | Activity::global());
+    QList<ResultSet::Result> documents;
+    for (const ResultSet::Result &result : results) {
+        if (result.url().isValid()) {
+            documents << result;
+        }
+    }
+    std::sort(documents.begin(), documents.end(), [](const ResultSet::Result &a, const ResultSet::Result &b) {
+        return QString::localeAwareCompare(documentName(a.url()), documentName(b.url())) < 0;
+    });
+    return documents;
+}
+
+QVariantList Backend::pinnedDocumentActions(const QUrl &launcherUrl, QObject *parent)
+{
+    QVariantList actions;
+    if (!parent) {
+        return actions;
+    }
+
+    const QUrl desktopEntryUrl = tryDecodeApplicationsUrl(launcherUrl);
+    const QString storageId = documentsAgent(desktopEntryUrl);
+
+    if (storageId.isEmpty()) {
+        return actions;
+    }
+
+    QList<QUrl> urls;
+    const auto documents = pinnedDocuments(storageId);
+    for (const ResultSet::Result &document : documents) {
+        actions << QVariant::fromValue<QAction *>(documentAction(document.url(), document.mimetype(), storageId, desktopEntryUrl, parent));
+        urls << document.url();
+    }
+
+    if (!urls.isEmpty()) {
+        QAction *separatorAction = new QAction(parent);
+        separatorAction->setSeparator(true);
+        actions << QVariant::fromValue<QAction *>(separatorAction);
+
+        actions << QVariant::fromValue<QAction *>(
+            pinDocumentsAction(i18nc("@action:inmenu", "Unpin File"), QStringLiteral("window-unpin"), urls, storageId, false, parent));
+    }
+
+    return actions;
+}
